inline void hashAppend(Hasher& hasher, const CustomOpAttributes* value)
{
    if(value == nullptr)
    {
        hasher.tag(0);
        return;
    }
    hasher.tag(1);
    {
        const auto* text = value->custom_op_id();
        hasher.raw(static_cast<uint32_t>(text == nullptr ? 0 : text->size()));
        if(text != nullptr)
        {
            for(char character : *text)
            {
                hasher.tag(static_cast<uint8_t>(character));
            }
        }
    }
    {
        const auto* items = value->input_tensor_uids();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hasher.raw(items->Get(index));
        }
    }
    {
        const auto* items = value->output_tensor_uids();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hasher.raw(items->Get(index));
        }
    }
    {
        const auto* items = value->data();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hasher.raw(items->Get(index));
        }
    }
}

