inline void hashAppend(Hasher& hasher, const Graph* value)
{
    if(value == nullptr)
    {
        hasher.tag(0);
        return;
    }
    hasher.tag(1);
    hasher.raw(static_cast<int64_t>(value->compute_data_type()));
    hasher.raw(static_cast<int64_t>(value->intermediate_data_type()));
    hasher.raw(static_cast<int64_t>(value->io_data_type()));
    {
        const auto* items = value->tensors();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hashAppend(hasher, items->Get(index));
        }
    }
    {
        const auto* items = value->nodes();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hashAppend(hasher, items->Get(index));
        }
    }
}

